mapper.select:
SELECT c.id as id, c.vlog_id as vlogId, v.title as vlogTitle, c.vloger_id as vlogerId, vloger.nickname as vlogerNickname, vloger.face as vlogerFace, c.comment_user_id as commentUserId, u.nickname as commentUserNickname, u.face as commentUserFace, c.father_comment_id as fatherCommentId, c.content as content, c.like_counts as likeCounts, fu.nickname as replyedUserNickname, c.is_deleted as isDeleted, c.create_time as createTime FROM `comment` as c LEFT JOIN users as u ON c.comment_user_id = u.id LEFT JOIN vlog as v ON c.vlog_id = v.id LEFT JOIN users as vloger ON c.vloger_id = vloger.id LEFT JOIN `comment` as fc ON c.father_comment_id = fc.id LEFT JOIN users as fu ON fc.comment_user_id = fu.id
c.vlog_id = #{paramMap.vlogId}
AND c.comment_user_id = #{paramMap.userId}
ORDER BY c.create_time DESC
